type Level = 'debug'|'info'|'warn'|'error';
interface ILogger { log(level: Level, msg: string): void }
interface IBackend { log(level: Level, msg: string): void }
class BackendRegistry {
  private factories = new Map<string, () => IBackend>();
  register(name: string, factory: () => IBackend) { this.factories.set(name, factory); }
  createAll(): IBackend[] { return Array.from(this.factories.values()).map(f => f()); }
